// Loads libduckdb and the Rust shim with bun:ffi. The libduckdb table and the
// shim's by-value wrappers are generated from DuckDB's C API spec
// (src/bindings/generated/capi.ts); the shim's own exports follow native/ABI.md.
import { CString, dlopen, type FFIFunction, FFIType, type Pointer } from "bun:ffi";
import packageJson from "../../../package.json" with { type: "json" };
import { nativePaths } from "../../library.ts";
import { byValue, capi } from "../generated/capi.ts";
import { debug, flags } from "./flags.ts";

/** The shim's exports from native/ABI.md, besides the generated by-value wrappers. */
const shimAbi = {
  dbs_init: { args: ["ptr", "ptr", "ptr"], returns: "i32" },
  dbs_set_sync_call: { args: ["ptr"], returns: "void" },
  dbs_context_close: { args: [], returns: "void" },
  dbs_counters: { args: [], returns: "ptr" },
  dbs_version: { args: [], returns: "cstring" },

  dbs_job_open: { args: ["ptr", "usize", "bool", "ptr"], returns: "ptr" },
  dbs_job_get_or_create_from_cache: { args: ["ptr", "ptr", "usize", "bool", "ptr"], returns: "ptr" },
  dbs_job_connect: { args: ["ptr"], returns: "ptr" },
  dbs_job_query: { args: ["ptr", "ptr", "usize"], returns: "ptr" },
  dbs_job_prepare: { args: ["ptr", "ptr", "usize"], returns: "ptr" },
  dbs_job_execute_prepared: { args: ["ptr"], returns: "ptr" },
  dbs_job_execute_prepared_streaming: { args: ["ptr"], returns: "ptr" },
  dbs_job_extract_statements: { args: ["ptr", "ptr", "usize"], returns: "ptr" },
  dbs_job_prepare_extracted_statement: { args: ["ptr", "ptr", "u64"], returns: "ptr" },
  dbs_job_execute_pending: { args: ["ptr"], returns: "ptr" },
  dbs_job_fetch_chunk: { args: ["ptr"], returns: "ptr" },
  dbs_job_failed: { args: ["ptr"], returns: "bool" },
  dbs_job_error: { args: ["ptr"], returns: "ptr" },
  dbs_job_out0: { args: ["ptr"], returns: "ptr" },
  dbs_job_out1: { args: ["ptr"], returns: FFIType.u64_fast },
  dbs_job_free: { args: ["ptr"], returns: "void" },

  dbs_scalar_function_set_callbacks: { args: ["ptr", "u64", "bool", "bool"], returns: "void" },
  dbs_table_function_set_callbacks: { args: ["ptr", "u64", "bool", "bool", "bool"], returns: "void" },
  dbs_set_bind_data: { args: ["ptr", "u32", "u64"], returns: "void" },
  dbs_get_bind_data: { args: ["ptr", "u32"], returns: FFIType.u64_fast },
  dbs_set_init_data: { args: ["ptr", "u64"], returns: "void" },
  dbs_get_init_data: { args: ["ptr"], returns: FFIType.u64_fast },
  dbs_get_local_init_data: { args: ["ptr"], returns: FFIType.u64_fast },
  dbs_scalar_init_set_state: { args: ["ptr", "u64"], returns: "void" },
  dbs_scalar_get_state: { args: ["ptr"], returns: FFIType.u64_fast },
  dbs_call_done: { args: ["ptr"], returns: "void" },

  dbs_ring_record: { args: ["u32", "u32", "u64", "u64", "ptr", "usize"], returns: "void" },
  dbs_install_crash_handler: { args: ["ptr", "usize"], returns: "i32" },
  dbs_crash_for_test: { args: ["u32"], returns: "void" },
} as const satisfies Record<string, FFIFunction>;

const paths = nativePaths();

// libduckdb first, by absolute path, so the shim's own dependency on it resolves
// to this already-loaded image.
export const duckdb = dlopen(paths.libPath, capi).symbols;
export const shim = dlopen(paths.shimPath, { ...byValue, ...shimAbi }).symbols;
export const libraryPath = paths.libPath;
export const shimPath = paths.shimPath;

/** The versions a crash report and diagnostics() name. */
export const versions = {
  package: packageJson.version,
  duckdb: new CString(duckdb.duckdb_library_version() as Pointer).toString(),
  bun: Bun.version,
  shim: String(shim.dbs_version()),
} as const;

debug(`loaded libduckdb ${versions.duckdb} from ${libraryPath}, shim ${versions.shim} from ${shimPath}`);

const CRASH_HANDLER_STATUS = ["installed", "failed: no alternate signal stack", "failed: sigaction"] as const;

/** The fatal-signal handler's state: native/ABI.md "Diagnostics". */
export const crashHandler: "disabled" | (typeof CRASH_HANDLER_STATUS)[number] = flags.crashHandler
  ? installCrashHandler()
  : "disabled";

function installCrashHandler(): (typeof CRASH_HANDLER_STATUS)[number] {
  const header = Buffer.from(
    `package ${versions.package}, duckdb ${versions.duckdb}, bun ${versions.bun}, shim ${versions.shim}`,
  );
  const status = CRASH_HANDLER_STATUS[shim.dbs_install_crash_handler(header, header.length)] ?? "failed: sigaction";
  // Queries work without the handler, so a failed install is not an error: diagnostics() reports it.
  debug(`crash handler ${status}`);
  return status;
}
